<template>
	<view class="container">
		<view class="header">
			<text class="title">消息中心</text>
		</view>
		
		<!-- 消息列表 -->
		<scroll-view class="message-list" scroll-y="true">
			<view class="message-item" v-for="message in messageList" :key="message.id" @click="openChat(message)">
				<view class="avatar-container">
					<image class="avatar" :src="message.avatar" mode="aspectFill"></image>
					<view class="unread-badge" v-if="message.unreadCount > 0">
						<text>{{ message.unreadCount > 99 ? '99+' : message.unreadCount }}</text>
					</view>
				</view>
				
				<view class="message-content">
					<view class="message-header">
						<text class="name">{{ message.name }}</text>
						<text class="time">{{ formatTime(message.lastTime) }}</text>
					</view>
					<view class="last-message">
						<text :class="{ unread: message.unreadCount > 0 }">{{ message.lastMessage }}</text>
					</view>
				</view>
			</view>
			
			<!-- 空状态 -->
			<view class="empty-state" v-if="messageList.length === 0">
				<image class="empty-icon" src="/static/xiaoxi_1.png" mode="aspectFit"></image>
				<text class="empty-text">暂无消息</text>
