<script setup>
import { ref, onMounted } from 'vue'

// 响应式数据
const messageList = ref([
	{
		id: 1,
		name: '张先生',
		avatar: '/static/user-placeholder.png',
		lastMessage: '谢谢您的帮助，陪诊服务很满意',
		lastTime: '2023-11-15 16:30',
		unreadCount: 0,
		orderId: 'PZ202311150001'
	},
	{
		id: 2,
		name: '李女士',
		avatar: '/static/user-placeholder.png',
		lastMessage: '请问您现在到医院了吗？',
		lastTime: '2023-11-16 09:15',
		unreadCount: 2,
		orderId: 'PZ202311160002'
	},
	{
		id: 3,
		name: '系统消息',
		avatar: '/static/logo.png',
		lastMessage: '您有新的订单待处理',
		lastTime: '2023-11-16 08:00',
		unreadCount: 1,
		type: 'system'
	}
])

// 生命周期
onMounted(() => {
	loadMessages()
})

// 方法定义
// 加载消息列表
const loadMessages = () => {
	// TODO: 调用后端API获取消息列表
	console.log('加载消息列表')
}

// 格式化时间
const formatTime = (timeStr) => {
	const now = new Date()
	// 将 "yyyy-MM-dd HH:mm" 格式转换为 iOS 兼容的 "yyyy/MM/dd HH:mm" 格式
	const compatibleTimeStr = timeStr.replace(/-/g, '/')
	const time = new Date(compatibleTimeStr)
	
	// 检查日期是否有效
	if (isNaN(time.getTime())) {
		console.error('Invalid date format:', timeStr)
		return timeStr // 返回原始字符串作为备用
	}
	
	const diff = now.getTime() - time.getTime()
	
	// 今天
	if (diff < 24 * 60 * 60 * 1000 && now.getDate() === time.getDate()) {
		return time.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
	}
	
	// 昨天
	if (diff < 48 * 60 * 60 * 1000) {
		return '昨天'
	}
	
	// 更早
	return time.toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit' })
}

// 打开聊天
const openChat = (message) => {
	if (message.type === 'system') {
		// 系统消息，跳转到通知详情
		uni.showToast({
			title: '系统消息详情',
			icon: 'none'
		})
		return
	}
	
	// 普通聊天消息
	uni.navigateTo({
		url: `/subpkg/chat/chat?userId=${message.id}&name=${message.name}`
	})
	
	// 清除未读数
	message.unreadCount = 0
}
</script>

